// 1. full stop + rebuild (not hot restart)   4. plugin supports this platform
// 2. flutter clean, pod install, gradle sync 5. isolate has a registrant
// 3. channel string identical on both sides  6. add-to-app registrant called

class PermissionPlugin : FlutterPlugin, ActivityAware, MethodCallHandler,
    PluginRegistry.RequestPermissionsResultListener {

    private var channel: MethodChannel? = null
    private var activity: Activity? = null           // only between attach/detach
    private var binding: ActivityPluginBinding? = null
    private var pending: MethodChannel.Result? = null

    override fun onAttachedToEngine(flutter: FlutterPlugin.FlutterPluginBinding) {
        channel = MethodChannel(flutter.binaryMessenger, "com.example/permissions")
        channel?.setMethodCallHandler(this)
    }

    override fun onAttachedToActivity(b: ActivityPluginBinding) {
        activity = b.activity
        binding = b
        b.addRequestPermissionsResultListener(this)
    }

    override fun onDetachedFromActivityForConfigChanges() = onDetachedFromActivity()

    override fun onReattachedToActivityForConfigChanges(b: ActivityPluginBinding) =
        onAttachedToActivity(b)

    override fun onDetachedFromActivity() {
        binding?.removeRequestPermissionsResultListener(this)  // ✅ no double calls
        binding = null
        activity = null                                        // ✅ no leaked Activity
    }

    override fun onMethodCall(call: MethodCall, result: MethodChannel.Result) {
        val current = activity
        if (current == null) {
            result.error("no_activity", "Plugin is not attached to an Activity", null)
            return
        }
        if (pending != null) {
            result.error("busy", "A permission request is already in flight", null)
            return
        }
        pending = result
        ActivityCompat.requestPermissions(current, arrayOf(call.arguments as String), 42)
    }

    override fun onRequestPermissionsResult(
        code: Int, permissions: Array<out String>, results: IntArray
    ): Boolean {
        if (code != 42) return false
        val granted = results.firstOrNull() == PackageManager.PERMISSION_GRANTED
        pending?.success(granted)      // exactly once, on the main thread
        pending = null
        return true
    }

    override fun onDetachedFromEngine(flutter: FlutterPlugin.FlutterPluginBinding) {
        channel?.setMethodCallHandler(null)
        channel = null
    }
}

