class Motion {
  static const _events = EventChannel('com.example/motion');

  // ✗ a new stream — and a second native onListen — on every call
  Stream<Sample> get raw => _events.receiveBroadcastStream().map(Sample.from);

  // ✓ created once, shared by every listener, batched on the native side
  static final Stream<List<Sample>> batches = _events
      .receiveBroadcastStream()
      .map((e) => Sample.decodeBatch(e! as Float64List));
}

// ✗ 200 events per second means 200 rebuilds per second
StreamBuilder<Sample>(
  stream: Motion().raw,
  builder: (_, snap) => Text('${snap.data?.x}'),
);

// ✓ push into a notifier; only the leaf that shows the number repaints
final tilt = ValueNotifier<double>(0);
final sub = Motion.batches.listen((batch) => tilt.value = batch.last.x);

RepaintBoundary(
  child: ValueListenableBuilder<double>(
    valueListenable: tilt,
    builder: (_, x, __) => Text(x.toStringAsFixed(2)),
  ),
);

