class Push {
  static const _channel = MethodChannel('com.example/push');

  // ✓ pull: survives the cold start because native kept the payload
  static Future<PushPayload?> initial() async {
    final map = await _channel.invokeMapMethod<String, Object?>('getInitialMessage');
    return map == null ? null : PushPayload.fromMap(map);
  }

  // ✓ push: for the warm case, registered as early as possible
  static void onOpened(void Function(PushPayload) handler) {
    _channel.setMethodCallHandler((call) async {
      if (call.method == 'onOpened') {
        handler(PushPayload.fromMap((call.arguments as Map).cast()));
      }
    });
  }
}

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // only if you genuinely need push-only delivery at startup
  ServicesBinding.instance.channelBuffers.resize('com.example/push', 8);
  Push.onOpened(router.openFromPush);
  runApp(App(initial: await Push.initial()));
}

