typedef _StartJobC = Void Function(
    Pointer<Utf8>, Pointer<NativeFunction<Void Function(Int32)>>);
typedef _StartJob = void Function(
    Pointer<Utf8>, Pointer<NativeFunction<Void Function(Int32)>>);

final _startJob = _dylib.lookupFunction<_StartJobC, _StartJob>('start_job');

class Job {
  Job(this.onProgress) {
    // ✓ safe from any thread: arguments are posted to this isolate's event loop
    _callback = NativeCallable<Void Function(Int32)>.listener(_onProgress);
  }

  final void Function(int percent) onProgress;
  late final NativeCallable<Void Function(Int32)> _callback;

  void _onProgress(int percent) => onProgress(percent);

  void start(String path) {
    final p = path.toNativeUtf8();
    _startJob(p, _callback.nativeFunction);
    calloc.free(p);            // safe only because start_job copies the string
  }

  // until this runs, the listener keeps the isolate alive
  void dispose() => _callback.close();
}

