class Tile {
  const Tile(this.z, this.x, this.y, this.bytes);
  final int z, x, y;
  final Uint8List bytes;
}

class TileCodec extends StandardMessageCodec {
  const TileCodec();

  static const int _tileTag = 128;   // 0..127 belong to the standard codec

  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is! Tile) return super.writeValue(buffer, value);
    buffer.putUint8(_tileTag);
    // delegate every field so nested and typed values keep the standard encoding
    super.writeValue(buffer, value.z);
    super.writeValue(buffer, value.x);
    super.writeValue(buffer, value.y);
    super.writeValue(buffer, value.bytes);   // typed data: aligned, no boxing
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    if (type != _tileTag) return super.readValueOfType(type, buffer);
    return Tile(
      readValue(buffer)! as int,
      readValue(buffer)! as int,
      readValue(buffer)! as int,
      readValue(buffer)! as Uint8List,
    );
  }
}

// the codec belongs to the channel object — construct both ends with it
const tiles = MethodChannel('com.example/tiles', StandardMethodCodec(TileCodec()));

